mapper.select:
SELECT te.ENTRY_ID as entryId, te.TRANSACTION_ID as transactionId, te.ENTRY_NO as entryNo, te.SUBJECT_ID as subjectId, te.DEBIT_AMOUNT as debitAmount, te.CREDIT_AMOUNT as creditAmount, te.CURRENCY_CODE as currencyCode, te.EXCHANGE_RATE as exchangeRate, te.AUXILIARY_INFO as auxiliaryInfo, te.BOOK_ID as bookId, te.TENANT_ID as tenantId, te.VERSION as version, te.CREATE_TIME as createTime, te.UPDATE_TIME as updateTime, te.CREATOR as creator, te.UPDATER as updater, s.SUBJECT_CODE as subjectCode, s.SUBJECT_NAME as subjectName FROM T_TRANSACTION_ENTRY te LEFT JOIN T_ACCOUNT_SUBJECT s ON te.SUBJECT_ID = s.SUBJECT_ID AND s.IS_DELETED = 0 WHERE te.IS_DELETED = 0
AND te.BOOK_ID = #{param.bookId}
AND te.TENANT_ID = #{param.tenantId}
AND te.TRANSACTION_ID = #{param.transactionId}
AND te.ENTRY_NO LIKE CONCAT('%', #{param.entryNo}, '%')
AND te.SUBJECT_ID = #{param.subjectId}
AND te.CURRENCY_CODE = #{param.currencyCode}
ORDER BY te.ENTRY_NO ASC

SELECT * FROM T_TRANSACTION_ENTRY 
WHERE IS_DELETED = 0 
AND ENTRY_NO = #{entryNo}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}

    AND ENTRY_ID != #{excludeId}

LIMIT 1

